V = [
(1, "Combien d'adresses d'hôtes utilisables contient le réseau 172.16.8.0/27 ?", ["30","32","62","14"], "A", "Un /27 laisse 5 bits d'hôte : 2^5 = 32 adresses, moins l'adresse réseau et l'adresse de broadcast = 30 hôtes."),
(2, "Un poste a l'adresse 10.20.30.77/26. Quelle est l'adresse de son réseau ?", ["10.20.30.0","10.20.30.127","10.20.30.64","10.20.30.76"], "C", "Masque /26 = 255.255.255.192 : les réseaux avancent de 64 en 64 (.0, .64, .128, .192) ; .77 appartient au réseau 10.20.30.64."),
(3, "Deux postes, 172.16.1.10/16 et 172.16.200.5/16, sont branchés sur le même switch, dans le même VLAN, sans routeur. Peuvent-ils communiquer ?", ["Non, car le troisième octet est différent : il faut un routeur","Oui, car avec un masque /16 les deux adresses sont dans le réseau 172.16.0.0","Non, car les adresses en 172.16.x sont privées et ne se routent pas entre elles","Oui, mais seulement si une passerelle par défaut est configurée sur chaque poste"], "B", "Avec un masque /16, seuls les deux premiers octets définissent le réseau : les deux postes sont dans 172.16.0.0/16 et communiquent directement, sans routeur."),
(4, "Sur un switch, le port qui relie un poste de travail appartenant uniquement au VLAN 20 doit être configuré en mode :", ["trunk","access","mirror","shutdown"], "B", "Un port access appartient à un seul VLAN et transmet des trames non étiquetées au poste ; le mode trunk sert aux liaisons qui transportent plusieurs VLAN."),
(5, "Sur un réseau, les postes récemment ajoutés obtiennent une adresse en 169.254.x.x, alors que les anciens postes fonctionnent normalement. Quelle est la cause la plus probable ?", ["Le serveur DNS ne résout pas les noms des nouveaux postes","La passerelle par défaut refuse les nouveaux postes","L'étendue (plage d'adresses) du serveur DHCP est épuisée","Les nouveaux postes ont un conflit d'adresse IP entre eux"], "C", "Une adresse 169.254.x.x (APIPA) signifie qu'aucun bail DHCP n'a été obtenu. Les anciens postes gardent leur bail : l'étendue n'a plus d'adresse libre pour les nouveaux."),
(6, "Cochez les protocoles qui utilisent principalement TCP (plusieurs réponses possibles) :", ["HTTPS","TFTP","NTP","FTP"], "A,D", "HTTPS (TCP 443) et FTP (TCP 21) utilisent TCP. TFTP (UDP 69) et NTP (UDP 123) utilisent UDP."),
(7, "Un serveur web interne en 192.168.10.5 doit être joignable depuis Internet via l'adresse publique de l'entreprise. Que configure-t-on sur le routeur ?", ["Un enregistrement DNS PTR pointant vers 192.168.10.5","Une réservation DHCP pour l'adresse 192.168.10.5","Un VLAN dédié au serveur, sans autre configuration","Une redirection de port (NAT de destination) vers 192.168.10.5"], "D", "La redirection de port (NAT de destination) renvoie vers le serveur interne les connexions qui arrivent sur l'adresse publique, pour le port choisi (443 par exemple)."),
(8, "Un poste a une adresse IP et un masque corrects, mais aucune passerelle par défaut n'est configurée. Que peut-il joindre ?", ["Uniquement les machines de son propre réseau local","Internet, mais pas les machines de son réseau local","Rien du tout : sans passerelle, la carte réseau est désactivée","Tous les réseaux, mais sans résolution de noms DNS"], "A", "Sans passerelle, le poste ne sait pas où envoyer les paquets destinés aux autres réseaux : il ne communique qu'avec son réseau local."),
(9, "Combien de sous-réseaux en /27 peut-on créer à partir d'un réseau en /24 ?", ["16","32","8","4"], "C", "On emprunte 3 bits d'hôte (27 - 24 = 3) : 2^3 = 8 sous-réseaux de 32 adresses chacun."),
(10, "Quelle commande Windows affiche la table de correspondance entre adresses IP et adresses MAC connue du poste ?", ["ipconfig /all","route print","nslookup","arp -a"], "D", "arp -a affiche le cache ARP du poste (adresse IP et adresse MAC associée). ipconfig /all ne donne que la MAC des cartes du poste lui-même."),
(11, "Les 20 commerciaux accèdent au dossier partagé « Ventes » grâce au groupe GG_Commerciaux. Un nouveau commercial arrive. Comment lui donner accès ?", ["L'ajouter au groupe GG_Commerciaux","Ajouter son compte dans les droits NTFS du dossier","Lui communiquer le mot de passe d'un collègue","Lui donner le Contrôle total sur le partage"], "A", "Les droits sont déjà donnés au groupe : il suffit d'y ajouter l'utilisateur. Ajouter des comptes un par un sur le dossier rend la gestion illisible."),
(12, "Un dossier est partagé avec le droit de partage « Modifier » pour « Utilisateurs authentifiés ». Julie, membre de ce groupe, a le droit NTFS « Contrôle total » sur ce dossier. Quel accès effectif Julie a-t-elle en passant par le réseau ?", ["Contrôle total","Lecture","Modification","Aucun accès"], "C", "Par le réseau, c'est la permission la plus restrictive entre droits de partage (Modifier) et droits NTFS (Contrôle total) qui s'applique : ici, Modification."),
(13, "Une GPO liée au domaine et une GPO liée à l'OU « Postes » définissent le même paramètre avec des valeurs différentes. Aucune option particulière n'est activée (ni « Appliqué », ni blocage de l'héritage). Quelle valeur s'applique aux ordinateurs de l'OU « Postes » ?", ["Celle de la GPO liée au domaine, car elle est de niveau supérieur","Aucune des deux, car le conflit bloque l'application du paramètre","Celle de la GPO créée le plus récemment dans la console de gestion","Celle de la GPO liée à l'OU, car elle est appliquée en dernier"], "D", "Les GPO s'appliquent dans l'ordre local, site, domaine, puis OU : en cas de conflit, la dernière appliquée (la plus proche de l'objet) l'emporte."),
(14, "Sous Linux, que donne la commande chmod 754 sur un fichier ?", ["Propriétaire : rwx / Groupe : rw- / Autres : r--","Propriétaire : rwx / Groupe : r-- / Autres : r-x","Propriétaire : r-x / Groupe : rwx / Autres : r--","Propriétaire : rwx / Groupe : r-x / Autres : r--"], "D", "7 = 4+2+1 (rwx), 5 = 4+1 (r-x), 4 = lecture seule (r--)."),
(15, "Sous Linux, quelle commande fait démarrer automatiquement le service ssh à chaque démarrage du système ?", ["systemctl start ssh","systemctl reload ssh","systemctl enable ssh","service ssh restart"], "C", "systemctl enable active le démarrage automatique du service. systemctl start le lance tout de suite, mais seulement jusqu'au prochain redémarrage."),
(16, "Un développeur doit seulement pouvoir redémarrer le service nginx sur un serveur Linux. Quelle solution respecte le principe du moindre privilège ?", ["L'ajouter au groupe sudo pour qu'il ait tous les droits root","Une règle sudoers l'autorisant à lancer seulement ce redémarrage","Lui donner le mot de passe root en lui demandant de se limiter à nginx","Faire un chmod 777 sur le binaire nginx pour qu'il puisse le relancer"], "B", "Le fichier sudoers permet de n'autoriser qu'une commande précise (ici systemctl restart nginx), de façon nominative et journalisée."),
(17, "Une entreprise sauvegarde chaque nuit son serveur sur un NAS situé dans la même salle. Que manque-t-il pour respecter la règle 3-2-1 ?", ["Une deuxième sauvegarde quotidienne sur le même NAS","Une troisième copie conservée hors site (autre bâtiment, cloud)","Un deuxième disque en RAID 1 dans le serveur","Une sauvegarde complète à la place des incrémentales"], "B", "Les données et le NAS font 2 copies, mais au même endroit. Il faut une troisième copie hors site ; un RAID n'est pas une sauvegarde."),
(18, "Quel type d'enregistrement DNS permet de retrouver le nom associé à une adresse IP (résolution inverse) ?", ["AAAA","CNAME","SRV","PTR"], "D", "PTR = résolution inverse (IP vers nom) ; AAAA = nom vers IPv6 ; CNAME = alias ; SRV = localisation d'un service (utilisé par Active Directory)."),
(19, "Un administrateur réseau quitte l'entreprise en mauvais termes. En plus de désactiver son compte nominatif, que faites-vous en priorité ?", ["Changer les mots de passe des comptes à privilèges et de service qu'il connaissait","Supprimer tous les fichiers qu'il a créés sur les serveurs de l'entreprise","Réinstaller l'ensemble des serveurs dont il avait la charge directe","Attendre la fin de son préavis pour vérifier ses dernières actions"], "A", "Désactiver son compte ne suffit pas : il connaît des secrets partagés (comptes admin, comptes de service, équipements). Il faut les changer immédiatement."),
(20, "Sous Linux, dans quel fichier sont stockées les empreintes (hash) des mots de passe des utilisateurs ?", ["/etc/passwd","/etc/group","/etc/shadow","/etc/sudoers"], "C", "/etc/shadow contient les empreintes des mots de passe et n'est lisible que par root ; /etc/passwd, lisible par tous, ne contient qu'un « x » à la place."),
(21, "Un utilisateur a ouvert la pièce jointe d'un mail suspect, et son poste se comporte de façon anormale. Quelle est l'action prioritaire ?", ["Débrancher le poste du réseau sans l'éteindre, puis prévenir l'équipe sécurité","Lancer une analyse antivirus complète et attendre le résultat avant d'agir","Éteindre et formater le poste pour éliminer le logiciel malveillant","Supprimer le mail et demander à l'utilisateur de continuer à travailler"], "A", "Isoler le poste empêche la propagation et les échanges avec l'attaquant ; le laisser allumé conserve les traces utiles à l'analyse."),
(22, "Le chiffrement complet du disque (BitLocker par exemple) d'un ordinateur portable protège principalement contre :", ["Un rançongiciel exécuté par l'utilisateur","Le vol d'un mot de passe par hameçonnage","La lecture des données si le portable est volé","Une attaque par déni de service (DDoS)"], "C", "Sans la clé, le disque d'un portable volé reste illisible. Une fois la session ouverte, les données sont déchiffrées : le chiffrement ne protège pas contre un malware."),
(23, "Cochez les bonnes pratiques pour sécuriser les comptes administrateurs d'un domaine Active Directory (plusieurs réponses possibles) :", ["Utiliser un compte d'administration distinct du compte utilisé au quotidien","Activer l'authentification multifacteur sur ces comptes","Limiter le nombre de membres du groupe « Admins du domaine »","Partager un seul compte administrateur entre tous les techniciens"], "A,B,C", "Un compte dédié, le MFA et un nombre réduit d'administrateurs limitent l'exposition. Un compte partagé empêche la traçabilité et circule trop facilement."),
(24, "Un compte de service sert uniquement à lire une base de données pour générer des rapports. Quels droits lui attribuer ?", ["Lecture seule sur la base concernée, et rien d'autre","Administrateur du serveur de base de données","Lecture et écriture sur toutes les bases, au cas où","Membre du groupe « Admins du domaine »"], "A", "Moindre privilège : le compte n'a que les droits nécessaires à sa mission. S'il est compromis, l'attaquant ne peut que lire cette base."),
(25, "Selon le RGPD, lorsqu'une violation de données personnelles présente un risque élevé pour les personnes, que doit faire l'organisme en plus de notifier l'autorité de contrôle ?", ["Informer les personnes concernées dans les meilleurs délais","Porter plainte dans tous les cas auprès de la police","Suspendre le traitement jusqu'à la décision de la CNIL","Publier un communiqué de presse dans les 72 heures"], "A", "Article 34 du RGPD : en cas de risque élevé, les personnes concernées doivent aussi être informées, pour qu'elles puissent se protéger."),
(26, "Pour qu'un IPS puisse bloquer le trafic malveillant, et pas seulement alerter, où doit-il être placé ?", ["Sur un port miroir (SPAN) du switch, qui reçoit une copie du trafic","Sur chaque poste client, à la place de l'antivirus","Sur le serveur DNS, pour filtrer les requêtes de noms","En coupure sur le chemin du trafic, que tout flux doit traverser"], "D", "Un IPS doit être en coupure (inline) pour pouvoir bloquer. Sur un port miroir, il ne voit qu'une copie du trafic : il ne peut qu'alerter, comme un IDS."),
(27, "Cochez les protocoles qui chiffrent les échanges (plusieurs réponses possibles) :", ["TFTP","IMAPS","SFTP","LDAPS"], "B,C,D", "IMAPS, SFTP et LDAPS sont des versions chiffrées (TLS ou SSH) de IMAP, du transfert de fichiers et de LDAP. TFTP transmet tout en clair, sans authentification."),
(28, "Pourquoi ajoute-t-on un sel (salt) avant de hacher un mot de passe ?", ["Pour pouvoir retrouver le mot de passe d'origine en cas d'oubli","Pour que deux mots de passe identiques n'aient pas la même empreinte","Pour compresser l'empreinte et réduire la taille de la base","Pour chiffrer le mot de passe avec une clé connue du serveur"], "B", "Le sel, aléatoire et propre à chaque compte, rend inutiles les tables d'empreintes précalculées et empêche de repérer les mots de passe identiques."),
(29, "Une personne en tenue de livreur suit de près un salarié pour franchir une porte à badge sans badger elle-même. De quoi s'agit-il ?", ["D'une pratique courante, sans enjeu de sécurité particulier","D'une attaque par hameçonnage ciblé (spear phishing)","D'une attaque par force brute sur le lecteur de badge","D'une intrusion physique par talonnage (tailgating)"], "D", "Le talonnage exploite la politesse pour contourner le contrôle d'accès physique. Chacun doit badger, et on oriente les visiteurs vers l'accueil."),
(30, "Un éditeur annonce qu'une faille critique de votre passerelle VPN est activement exploitée, mais aucun correctif n'est encore disponible. Que faites-vous ?", ["Ne rien faire tant que le correctif n'est pas publié par l'éditeur","Appliquer les contournements de l'éditeur et surveiller les accès VPN","Réinstaller le VPN dans sa version actuelle pour repartir sur une base saine","Redémarrer le boîtier VPN chaque jour pour effacer une éventuelle intrusion"], "B", "En attendant le correctif, on réduit l'exposition avec les mesures de contournement publiées et on surveille les journaux pour détecter une compromission."),
(31, "Que produit ce script Bash ?\nfor i in $(seq 2 4); do\n    echo \"VM$i\"\ndone", ["VM2 et VM4, sur deux lignes","VM$i, trois fois, sur trois lignes","VM2, VM3 et VM4, sur trois lignes","VM1, VM2, VM3 et VM4, sur quatre lignes"], "C", "seq 2 4 produit 2, 3 et 4 ; la variable i prend successivement ces valeurs et echo affiche une ligne à chaque tour."),
(32, "Qu'affiche ce code Python ?\nnote = 12\nif note >= 15:\n    print(\"Bien\")\nelif note >= 10:\n    print(\"Admis\")\nelse:\n    print(\"Refusé\")", ["Bien","Refusé","Bien puis Admis","Admis"], "D", "12 >= 15 est faux, 12 >= 10 est vrai : seul le bloc elif est exécuté, le else est ignoré."),
(33, "Qu'affiche ce code Python ?\nvlans = [10, 20, 30, 40]\nprint(len(vlans), vlans[2])", ["4 20","3 30","5 30","4 30"], "D", "len() renvoie 4 éléments ; les index commencent à 0, donc vlans[2] est le troisième élément, 30."),
(34, "Que fait cette commande PowerShell ?\nGet-Service | Where-Object { $_.Status -eq \"Stopped\" }", ["Elle arrête tous les services en cours d'exécution","Elle liste les services en cours d'exécution","Elle liste les services arrêtés","Elle redémarre tous les services arrêtés"], "C", "Get-Service récupère les services, Where-Object ne garde que ceux dont le statut est « Stopped ». Rien n'est modifié."),
(35, "Un script deploy.sh commence bien par #!/bin/bash, mais ./deploy.sh renvoie « Permission denied ». Quelle commande corrige le problème ?", ["chmod +x deploy.sh","chmod 644 deploy.sh","chown root deploy.sh","bash -n deploy.sh"], "A", "Il manque le droit d'exécution : chmod +x l'ajoute. chmod 644 ne donne que lecture et écriture, et bash -n vérifie seulement la syntaxe."),
(36, "Que fait cette commande ?\ngrep -v \"^#\" /etc/ssh/sshd_config | grep -v \"^$\"", ["Elle affiche uniquement les lignes de commentaire du fichier","Elle réécrit le fichier sans les commentaires ni les lignes vides","Elle compte les lignes non commentées du fichier","Elle affiche les lignes qui ne sont ni des commentaires ni vides"], "D", "grep -v inverse le filtre : on retire les lignes commençant par # puis les lignes vides. Le fichier n'est pas modifié ; on obtient la configuration réellement active."),
(37, "Qu'affiche ce code Python ?\ncompteur = 10\nwhile compteur > 4:\n    compteur -= 3\nprint(compteur)", ["4","1","7","Rien : la boucle est infinie"], "A", "compteur passe de 10 à 7, puis à 4 ; la condition 4 > 4 est fausse, la boucle s'arrête et affiche 4."),
(38, "Un développeur a publié par erreur, sur un dépôt Git public, un fichier contenant une clé d'API de production. Il a supprimé ce fichier dans un nouveau commit. Est-ce suffisant ?", ["Oui, car le fichier n'apparaît plus dans la dernière version du dépôt","Oui, si le dépôt est repassé en privé dans l'heure qui suit","Non : la clé reste dans l'historique, il faut la révoquer et la remplacer","Non : il faut supprimer le dépôt, ce qui rend la clé inutilisable"], "C", "L'historique Git conserve le fichier, et la clé a pu être copiée entre-temps. Un secret exposé doit toujours être révoqué et remplacé."),
(39, "Que fait ce script Bash ?\nif [ -d /var/backups ]; then\n    echo \"Présent\"\nelse\n    echo \"Absent\"\nfi", ["Il crée le répertoire /var/backups s'il n'existe pas","Il affiche Présent si /var/backups est un répertoire existant, sinon Absent","Il affiche Présent si /var/backups est un fichier ordinaire, sinon Absent","Il affiche le contenu du répertoire /var/backups"], "B", "Le test -d vérifie qu'un répertoire existe (-f teste un fichier ordinaire). Selon le résultat, c'est la branche then ou la branche else qui s'exécute."),
(40, "Qu'affiche ce code Python ?\nports = [21, 22, 80, 443, 8080]\nfor p in ports:\n    if p > 100:\n        print(p)", ["21, 22 et 80","443 et 8080","80, 443 et 8080","Rien"], "B", "La boucle parcourt la liste et n'affiche que les ports strictement supérieurs à 100 : 443 et 8080."),
(41, "Un poste en adressage IP fixe répond au ping vers 192.168.1.1, le routeur de son réseau, mais pas vers 8.8.8.8. Les autres postes accèdent normalement à Internet. Que vérifiez-vous en premier sur ce poste ?", ["La configuration du serveur DNS","Le câble réseau","La passerelle par défaut configurée","Le pilote de la carte réseau"], "C", "Le réseau local fonctionne (le routeur répond) et le DNS n'intervient pas dans un ping vers une adresse IP : le poste n'envoie sans doute pas son trafic vers la bonne passerelle."),
(42, "Un seul utilisateur n'arrive plus à ouvrir un site web interne, alors que ses collègues du même service y accèdent sans problème. Où cherchez-vous en priorité ?", ["Sur le serveur web interne, qui est peut-être arrêté","Sur le pare-feu Internet de l'entreprise","Sur le serveur DNS interne, qui ne résout plus le nom du site","Sur le poste : navigateur, proxy, fichier hosts, cache DNS"], "D", "Les collègues accèdent au site : le serveur, le DNS et le réseau fonctionnent. On cherche donc ce qui est propre à ce poste."),
(43, "Un matin, plus aucun poste de l'entreprise n'accède à Internet, mais les serveurs internes (fichiers, intranet) restent joignables. Quelle est la cause la plus probable ?", ["Un problème sur le switch d'un des étages du bâtiment","Une panne du routeur Internet ou de la liaison opérateur","Des cartes réseau défectueuses sur l'ensemble des postes","Une GPO qui aurait modifié les adresses IP de tous les postes"], "B", "Le réseau interne fonctionne pour tout le monde, seul l'accès à Internet est coupé : on cherche l'équipement commun à ce seul flux, le routeur ou le lien vers l'opérateur."),
(44, "Un poste n'arrive pas à joindre le contrôleur de domaine par son nom, dc01.lab.local. Quelle commande permet de tester la résolution de ce nom auprès du serveur DNS ?", ["gpupdate /force","ipconfig /flushdns","netstat -ano","nslookup dc01.lab.local"], "D", "nslookup interroge le serveur DNS et affiche l'adresse obtenue. ipconfig /flushdns vide le cache local mais ne teste rien."),
(45, "Plusieurs tickets arrivent au support au même moment. Lequel prenez-vous en charge en premier ?", ["Un nouvel arrivant demande un logiciel pour la semaine prochaine","Un utilisateur cherche un fichier supprimé il y a un mois","Le serveur de paie est inaccessible la veille du versement des salaires","Le Wi-Fi est lent en salle de réunion, mais le filaire fonctionne"], "C", "La priorité dépend de l'impact et de l'urgence : un service critique bloqué avec une échéance immédiate passe avant le reste."),
(46, "À l'ouverture de session, un poste du domaine affiche : « Il n'y a actuellement aucun serveur d'ouverture de session disponible pour traiter la demande d'ouverture de session. » Que signifie ce message ?", ["Le mot de passe saisi par l'utilisateur est incorrect ou a expiré","Le poste ne parvient à joindre aucun contrôleur de domaine (réseau ou DNS)","La licence Windows du poste a expiré et doit être réactivée","Le profil local de l'utilisateur est corrompu et doit être recréé"], "B", "Le poste ne trouve aucun contrôleur de domaine pour vérifier l'identité de l'utilisateur : on vérifie la connexion réseau et la configuration DNS du poste."),
(47, "En vous connectant en SSH à un serveur, vous obtenez l'avertissement « WARNING: REMOTE HOST IDENTIFICATION HAS CHANGED! ». Que peut-on en déduire ?", ["La clé d'hôte du serveur a changé : réinstallation ou possible interception","Le mot de passe de votre compte sur le serveur a été modifié par l'administrateur","Le service SSH n'écoute plus sur le port 22 et a été déplacé sur un autre port","Votre clé SSH privée a expiré et doit être régénérée sur votre poste"], "A", "La clé présentée par le serveur ne correspond plus à celle enregistrée dans known_hosts. Avant d'accepter, on vérifie si le serveur a été réinstallé ou s'il s'agit d'une attaque de l'homme du milieu."),
(48, "Vous devez redémarrer un serveur de fichiers en production pour appliquer des mises à jour. Quelles précautions prenez-vous (plusieurs réponses possibles) ?", ["Vérifier qu'une sauvegarde récente et restaurable existe","Prévenir les utilisateurs et choisir un créneau de faible activité","Redémarrer en pleine journée pour voir tout de suite les problèmes","Contrôler après redémarrage que les services et partages répondent"], "A,B,D", "Une intervention en production se prépare (sauvegarde, communication, créneau adapté) et se vérifie ensuite ; on évite les heures de forte activité."),
(49, "Chaque lundi vers 9 h, de nombreux utilisateurs signalent que l'ouverture de session prend plusieurs minutes ; le reste de la semaine, tout est normal. Quelle hypothèse vérifiez-vous en premier ?", ["Une surcharge due aux postes qui démarrent et se mettent à jour en même temps","Un câble réseau défectueux entre le contrôleur de domaine et le switch","Une panne matérielle du disque dur de chacun des postes concernés","Un virus programmé pour se déclencher uniquement le lundi matin"], "A", "Un problème qui revient à un moment précis, pour beaucoup d'utilisateurs à la fois, oriente vers un pic de charge (connexions, GPO, mises à jour) plutôt que vers une panne matérielle."),
(50, "Un utilisateur appelle le support pour faire réinitialiser son mot de passe. Vous ne reconnaissez pas sa voix et il insiste sur l'urgence. Que faites-vous ?", ["Réinitialiser le mot de passe tout de suite et le lui dicter au téléphone","Vérifier son identité (rappel au numéro de l'annuaire interne) avant de réinitialiser","Refuser définitivement toute réinitialisation de mot de passe par téléphone","Envoyer le nouveau mot de passe à l'adresse mail personnelle qu'il vous indique"], "B", "L'urgence est un levier classique d'ingénierie sociale : on vérifie l'identité par un canal connu avant toute réinitialisation."),
]
